import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.DYAmjhAm.js";const f=JSON.parse('{"title":"Interface: NodeMeta","description":"","frontmatter":{},"headers":[],"relativePath":"api/interfaces/NodeMeta.md","filePath":"api/interfaces/NodeMeta.md","lastUpdated":null}'),d={name:"api/interfaces/NodeMeta.md"};function n(s,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">breeze-client</a> / NodeMeta</p><h1 id="interface-nodemeta" tabindex="-1">Interface: NodeMeta <a class="header-anchor" href="#interface-nodemeta" aria-label="Permalink to &quot;Interface: NodeMeta&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L220" target="_blank" rel="noreferrer">src/metadata/data-service.ts:220</a></p><p>What a <a href="./../classes/JsonResultsAdapter">JsonResultsAdapter</a>&#39;s <code>visitNode</code> returns for one node of a query or save result, telling Breeze how to treat it. Every property is optional; returning <code>{}</code> (or nothing) treats the node as plain data.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="entitytype" tabindex="-1">entityType? <a class="header-anchor" href="#entitytype" aria-label="Permalink to &quot;entityType?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>entityType?</strong>: <a href="./../classes/EntityType"><code>EntityType</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L222" target="_blank" rel="noreferrer">src/metadata/data-service.ts:222</a></p><p>The type of entity or complex object this node is, or its name. When set, Breeze materializes the node as an entity of that type and merges it into the cache (unless the query is <code>noTracking</code>); a complex type is mapped without merging. For a top-level query result with no type, Breeze uses the query&#39;s result type.</p><hr><h3 id="extrametadata" tabindex="-1">extraMetadata? <a class="header-anchor" href="#extrametadata" aria-label="Permalink to &quot;extraMetadata?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>extraMetadata?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L232" target="_blank" rel="noreferrer">src/metadata/data-service.ts:232</a></p><p>Anything else about the node to keep. Breeze stores it on the entity&#39;s <code>entityAspect.extraMetadata</code>.</p><hr><h3 id="ignore" tabindex="-1">ignore? <a class="header-anchor" href="#ignore" aria-label="Permalink to &quot;ignore?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>ignore?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L228" target="_blank" rel="noreferrer">src/metadata/data-service.ts:228</a></p><p>Whether to skip this node. A skipped property is left off the object that holds it; a skipped top-level node is dropped from the results (or is <code>null</code> there, when the query includes deleted entities).</p><hr><h3 id="node" tabindex="-1">node? <a class="header-anchor" href="#node" aria-label="Permalink to &quot;node?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>node?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L234" target="_blank" rel="noreferrer">src/metadata/data-service.ts:234</a></p><p>Use this object in place of the node that was visited.</p><hr><h3 id="nodeid" tabindex="-1">nodeId? <a class="header-anchor" href="#nodeid" aria-label="Permalink to &quot;nodeId?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>nodeId?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L224" target="_blank" rel="noreferrer">src/metadata/data-service.ts:224</a></p><p>An id for this node, such as a Json.NET <code>$id</code>, that other nodes can refer to with <code>nodeRefId</code>.</p><hr><h3 id="noderefid" tabindex="-1">nodeRefId? <a class="header-anchor" href="#noderefid" aria-label="Permalink to &quot;nodeRefId?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>nodeRefId?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L226" target="_blank" rel="noreferrer">src/metadata/data-service.ts:226</a></p><p>The <code>nodeId</code> of another node that this node stands for, such as a Json.NET <code>$ref</code>. Breeze returns the entity or object read from that node in its place.</p><hr><h3 id="passthru" tabindex="-1">passThru? <a class="header-anchor" href="#passthru" aria-label="Permalink to &quot;passThru?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>passThru?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/data-service.ts#L230" target="_blank" rel="noreferrer">src/metadata/data-service.ts:230</a></p><p>Whether to keep the node exactly as the server sent it, without mapping its property names to the client&#39;s or visiting what it contains. Ignored for a top-level node that has an <code>entityType</code>, which is merged as an entity.</p>',39)])])}const b=t(d,[["render",n]]);export{f as __pageData,b as default};
